let pres = new pptx();

// Set layout to 16x9
pres.layout = pptx.LAYOUT_16x9;

// Define a theme
pres.defineTheme({
  name: 'myTheme',
  colors: {
    dark: '000000',
    light: 'FFFFFF',
    accent1: '4472C4',
    accent2: 'ED7D31',
    accent3: 'A5A5A5',
    accent4: 'FFC000',
    accent5: '5B9BD5',
    accent6: '70AD47'
  }
});

// Slide 1: Title Slide
let slide1 = pres.addSlide();
slide1.addText('Sample Presentation', { x: 0.5, y: 0.5, w: 9, h: 1, fontSize: 32, color: '000000', align: 'center' });
slide1.addText('Created by TITAN Assistant', { x: 0.5, y: 2, w: 9, h: 0.5, fontSize: 20, color: '000000', align: 'center' });

// Slide 2: Bullet Points
let slide2 = pres.addSlide();
slide2.addText('Agenda', { x: 0.5, y: 0.5, w: 9, h: 0.5, fontSize: 24, color: '000000', bold: true });
slide2.addText([
  'Introduction',
  'Main Topic',
  'Details',
  'Conclusion'
], { x: 0.5, y: 1.5, w: 9, h: 2, fontSize: 18, color: '000000', bullet: true });

// Slide 3: Chart (simple bar chart)
